import json,numpy as np
m=json.load(open('/app/output/clear_tree/hold/meta.json'));C=np.array(m['cameras']['robot_r1:zed_link:Camera:0']['cam2world_gl']);p=np.load('/app/output/clear_tree/hold/proprio.npy')[-1];yaw=2*np.arctan2(p[33],p[34]);print('base',p[28:35], 'yaw',yaw);print('cam pos',C[:3,3], 'right',C[:3,0], 'up',C[:3,1], 'forward',-C[:3,2]);
for uv in [(112,170),(112,140),(150,170),(75,170)]:
 x=(uv[0]-112)/95.2;y=-(uv[1]-112)/95.2;d=C[:3,:3]@np.array([x,y,-1]);d=d/np.linalg.norm(d);print(uv,np.round(d,3))
PY

