import json,numpy as np
m=json.load(open('/app/output/trees_approach2/hold/meta.json'));C=np.array(m['cameras']['robot_r1:zed_link:Camera:0']['cam2world_gl']);K=np.array(m['cameras']['robot_r1:zed_link:Camera:0']['intrinsic_cv']);p=np.load('/app/output/trees_approach2/hold/proprio.npy')[-1];yaw=2*np.arctan2(p[33],p[34]);print('base',p[28:35],'yaw',yaw,'forward',[np.cos(yaw),np.sin(yaw)],'ray',-C[:3,2],'right',C[:3,0]);
for uv in [(178,135),(178,120),(112,150)]:
 x=(uv[0]-112)/95.2;y=-(uv[1]-112)/95.2;d=C[:3,:3]@np.array([x,y,-1]);d/=np.linalg.norm(d);dx=np.cos(yaw)*d[0]+np.sin(yaw)*d[1];dy=-np.sin(yaw)*d[0]+np.cos(yaw)*d[1];print(uv,d,'local',dx,dy)
