import json,numpy as np
for d in ['egg_reach_base_shift','egg_cluster_wrist_scan','egg_scan_local','egg_near_align','push_cluster4','arm_resettle']:
 try:m=json.load(open(f'/app/output/{d}/meta.json'))
 except:continue
 c=m['cameras']['robot_r1:zed_link:Camera:0'];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:3,:3];t=E[:3,3];o=-R.T@t
 print('\n',d,'origin=',np.round(o,3),'rot=',np.round(np.array(c['cam2world_gl'])[:3,:3],2))
 uvlist=[(2,42),(2,87),(68,163),(92,210),(66,165),(90,200)]
 for u,v in uvlist:
  ray=R.T@np.linalg.inv(K)@np.array([u,v,1.]);s=-o[2]/ray[2]
  if 0<s<10: print((u,v),np.round(o+s*ray,3))
